Title: Question about: enableRateLimit': true
Description: OS: Windows 10
Programming Language version: Node.js
CCXT version: #465
Exchange: Binance
Node.js 11.9.0 installed
Method: exchange.fetchOrderBook

Hello!

I have a working code below to get the orderbooks for 3 symbols in a loop at Binance.

My question is about the ratelimit. I know Binance has 1200 requests/minute but I am a bit confused when I see the below ratelimit information.

**Should I in my code use: 'enableRateLimit': true ?**

enableRateLimit': true (Takes 3 seconds)
**enableRateLimit': false (Takes 1 second) This is not a good idéa to do?**

Assume that I only would run this code once every minute which would be clearly below 1200 requests/minute. Is there Also a limit as the manual says to ONLY do 1 HTTP requests per 2000 milliseconds as this also can get ones IP banned?


`**"rateLimits": [{
    "rateLimitType": "REQUESTS",
    "interval": "MINUTE",
    "limit": 1200
  },**

### _"rateLimit: A request rate limit in milliseconds. Specifies the required minimal delay between two consequent HTTP requests to the same exchange"_`

```javascript
'use strict';
const ccxt = require('ccxt');
const fs = require('fs');
const path = require('path');


var i;
const exchangename = "binance";
const exchange = new ccxt.binance({
    'enableRateLimit': true
});

(async () => {
    console.log(`start`);
    const start = Date.now();


    var orderbookPromises = []
    var symbols = ['ETH/BTC', 'LTC/BTC', 'ZRX/ETH']
    for (i = 0; i < symbols.length; i++) {

        const symbol = symbols[i]
        
        try {
                let tickerProcessing = new Promise(async (resolve) => {
                    const orderbook = await exchange.fetchOrderBook(symbol, 5);

                    const exchangename2 = exchangename + '#' + symbol.replace("/", "")
                    const dumpFile = path.join(__dirname, 'orderbooks', `${exchangename2}Orderbook.txt`);
                await fs.promises.writeFile(dumpFile, JSON.stringify(orderbook));
                resolve()
            })
            orderbookPromises.push(tickerProcessing)

        } catch (e) {
            console.error(e);
        }
    }

    // wait for all of them to execute or fail
    await Promise.all(orderbookPromises)


    const end = Date.now();
    console.log(`Done in ${(end - start) / 1000} seconds`);
})();

```


